package com.narudzbine.audit.infrastructure;
import static org.assertj.core.api.Assertions.*;
import com.narudzbine.audit.api.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.transaction.support.TransactionSynchronizationManager;
class FileIndependentObjectStoreTest {
 @TempDir Path temp;
 private IndependentObjects.Key key(long sequence){return new IndependentObjects.Key(IndependentObjects.Family.DELETION_INTENT,UUID.fromString("019a0000-0000-7000-8000-000000000001"),sequence);}
 private FileIndependentObjectStore store()throws Exception{return new FileIndependentObjectStore(Files.createDirectory(temp.resolve("private")));}
 @Test void conditionalPublicationNeverReplacesRetainedBytes()throws Exception{var store=store();assertThat(store.read(key(1))).isEmpty();assertThat(store.create(key(1),new byte[]{1,2,3})).isTrue();assertThat(store.create(key(1),new byte[]{4})).isFalse();assertThat(store.read(key(1)).orElseThrow()).isEqualTo(new byte[]{1,2,3});try(var entries=Files.list(temp.resolve("private/.prepared"))){assertThat(entries.count()).isZero();}}
 @Test void actualCompetingPublishersHaveExactlyOneWinner()throws Exception{var store=store();var start=new CountDownLatch(1);try(var executor=Executors.newFixedThreadPool(2)){var first=executor.submit(()->{start.await();return store.create(key(1),new byte[]{1});});var second=executor.submit(()->{start.await();return store.create(key(1),new byte[]{2});});start.countDown();boolean a=first.get(5,TimeUnit.SECONDS),b=second.get(5,TimeUnit.SECONDS);assertThat(a).isNotEqualTo(b);assertThat(store.read(key(1)).orElseThrow()).isEqualTo(new byte[]{(byte)(a?1:2)});}}
 @Test void boundedListingsUseCanonicalIdentityOrderAndNoPartialInvalidEntries()throws Exception{var store=store();for(long n:new long[]{5,2,1,4,3})store.create(key(n),new byte[]{1});var page=store.list(key(1).family(),2,null);assertThat(page.keys()).containsExactly(key(1),key(2));assertThat(page.more()).isTrue();var next=store.list(key(1).family(),2,key(2));assertThat(next.keys()).containsExactly(key(3),key(4));assertThat(next.more()).isTrue();assertThat(store.list(key(1).family(),2,key(4)).keys()).containsExactly(key(5));assertThat(store.list(key(1).family(),2,key(4)).more()).isFalse();Files.write(temp.resolve("private").resolve(key(1).family().path()).resolve(key(1).resource().toString()).resolve("invalid.bin"),new byte[]{1});assertThatThrownBy(()->store.list(key(1).family(),2,null)).isInstanceOf(EvidenceFailure.class);}
 @Test void unknownEmptyResourceDirectoriesFailRatherThanSilentlyDisappearing()throws Exception{var store=store();store.create(key(1),new byte[]{1});Files.createDirectory(temp.resolve("private").resolve(key(1).family().path()).resolve("invalid-resource"));assertThatThrownBy(()->store.list(key(1).family(),2,null)).isInstanceOf(EvidenceFailure.class);}
 @Test void redirectedParentDirectoryCannotEscapeThePrivateRoot()throws Exception{
  var store=store();Path outside=Files.createDirectory(temp.resolve("owned-other")),link=temp.resolve("private").resolve(key(1).family().path());
  if(System.getProperty("os.name").toLowerCase(Locale.ROOT).contains("win")){var process=new ProcessBuilder("cmd.exe","/c","mklink","/J",link.toString(),outside.toString()).redirectErrorStream(true).start();process.getInputStream().readAllBytes();assertThat(process.waitFor()).as("local owned junction fixture creation").isZero();}
  else Files.createSymbolicLink(link,outside);
  assertThatThrownBy(()->store.create(key(1),new byte[]{1})).isInstanceOf(EvidenceFailure.class);assertThatThrownBy(()->store.read(key(1))).isInstanceOf(EvidenceFailure.class);assertThatThrownBy(()->store.list(key(1).family(),1,null)).isInstanceOf(EvidenceFailure.class);try(var files=Files.list(outside)){assertThat(files.count()).isZero();}
  Files.delete(link);
 }
 @Test void nonRegularObjectsAndOversizedFilesFailClosed()throws Exception{var store=store();store.create(key(1),new byte[]{1});Path path=temp.resolve("private").resolve(key(1).path());Files.delete(path);Files.createDirectory(path);assertThatThrownBy(()->store.read(key(1))).isInstanceOf(EvidenceFailure.class);assertThatThrownBy(()->store.create(key(1),new byte[]{1})).isInstanceOf(EvidenceFailure.class);Files.delete(path);try(var channel=java.nio.channels.FileChannel.open(path,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE)){channel.position(IndependentObjects.MAX_OBJECT);channel.write(java.nio.ByteBuffer.wrap(new byte[]{1}));}assertThatThrownBy(()->store.read(key(1))).isInstanceOf(EvidenceFailure.class);}
 @Test void localFileIoAndConstructionAreRejectedInsideTransactions()throws Exception{var store=store();TransactionSynchronizationManager.setActualTransactionActive(true);try{assertThatThrownBy(()->store.create(key(1),new byte[]{1})).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->store.read(key(1))).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->store.list(key(1).family(),1,null)).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->new FileIndependentObjectStore(temp)).isInstanceOf(IllegalStateException.class);}finally{TransactionSynchronizationManager.setActualTransactionActive(false);}}
 @Test void localEncryptedEvidenceSurvivesANewAdapterInstance()throws Exception{Path root=Files.createDirectory(temp.resolve("private"));byte[] keyBytes=new byte[32];keyBytes[0]=1;var first=new IndependentEvidence(new FileIndependentObjectStore(root),Map.of("v1",keyBytes),"v1",List.of());byte[] plain="Synthetic durable-to-reopen fixture".getBytes(java.nio.charset.StandardCharsets.UTF_8);var receipt=first.ensure(key(1),plain);var reopened=new IndependentEvidence(new FileIndependentObjectStore(root),Map.of("v1",keyBytes),"v1",List.of());assertThat(reopened.ensure(key(1),plain)).isEqualTo(receipt);assertThat(reopened.read(key(1)).orElseThrow().bytes()).isEqualTo(plain);assertThat(new String(Files.readAllBytes(root.resolve(key(1).path())),java.nio.charset.StandardCharsets.UTF_8)).doesNotContain("Synthetic durable-to-reopen fixture");}
}
